// Symmetric d^{abc} codegen gate (kernels generated by tests/gen/gen_dsym_numeric.wls): ntSUNd through
// emission, the colour-Plus lowering, a generator trace and the per-component dressed fold, graded
// against the analytic SU(3) values derived in the generator script.
#include "Dsymdd_num_kernel.hh"
#include "Dsymdiag_num_kernel.hh"
#include "Dsymdttt_num_kernel.hh"
#include "Dsymsum_num_kernel.hh"

#include <cmath>
#include <cstdio>

int main()
{
  int fails = 0;
  auto check = [&](const char *what, double got, double want) {
    const double err = std::abs(got - want) / std::max(1.0, std::abs(want));
    const bool ok = err < 1e-12;
    std::printf("%s %-36s got % .15e want % .15e\n", ok ? "  ok  " : "FAIL ", what, got, want);
    if (!ok) ++fails;
  };
  auto Zq = [](double y) { return 1.0 + y; };
  auto Mq = [](double y) { return 0.3 + y * y; };
  auto ZA8 = [](double y) { return 0.7 + y; };
  auto ZA4 = [](double y) { return 2.0 - 0.5 * y; };
  const double pts[][5] = {{0.7, 1.3, 0.35, 0.9, 1.1}, {-1.2, 0.6, -0.8, 0.3, 2.0}};
  for (const auto &x : pts) {
    const double l0 = x[0], l1 = x[1], cos1 = x[2], p0 = x[3], p = x[4];
    const double lp = l0 * p0 + l1 * cos1 * p;
    using namespace numtracer_kernels;
    check("Zq tr(lslash pslash) d.d", Dsymdd_num_kernel::kernel(l0, l1, cos1, p0, p, Zq), 160.0 / 3.0 * lp * Zq(l1));
    check("Mq tr1 d tr(TTT)", Dsymdttt_num_kernel::kernel(l0, l1, cos1, p0, p, Mq), 40.0 / 3.0 * Mq(l1));
    check("tr(lslash pslash) d.(d + f)", Dsymsum_num_kernel::kernel(l0, l1, cos1, p0, p), 160.0 / 3.0 * lp);
    check("tr1 d d diag(lambda8) diag(lambda4)", Dsymdiag_num_kernel::kernel(l0, l1, cos1, p0, p, ZA8, ZA4),
          ZA8(l1) * ZA4(l1) / 3.0);
  }
  if (fails) {
    std::printf("%d check(s) FAILED\n", fails);
    return 1;
  }
  std::printf("symmetric d^{abc} kernels agree with the analytic values\n");
  return 0;
}
